// Define a function to calculate the optimal bid in a first-price sealed-bid auction. 

// Inputs: 
// - private_value: The bidder's private valuation of the item.
// - bids: An array of objects where each object contains 'bid' and 'probability' of winning.

// Returns: The optimal bid to maximize expected profit.

function optimalBid(private_value, bids) {
  let maxProfit = 0;
  let optimalBid = 0;

  for (let bid of bids) {
    const profit = (private_value - bid.bid) * bid.probability;
    if (profit > maxProfit) {
      maxProfit = profit;
      optimalBid = bid.bid;
    }
  }

  return optimalBid;
}

