module.exports = function firstPriceAuction(privateValue, bids) {
  let maxProfit = 0;
  let bestBid = 0;

  bids.forEach(bid => {
    const profit = (privateValue - bid.bid) * bid.prob;
    if (profit > maxProfit) {
